// THE PROP KIT — every placeable prop Josh owns, as the map sees it.
//
// The catalogue (props-catalog.json) is GENERATED by scripts/props/build.mjs
// from the hand-curated list in scripts/props/curate.mjs; this module is the
// one place the game reads it. Imports nothing but the JSON, so the client's
// map editor shares it verbatim.
//
// COORDINATES. A prop sits at (x, y) in CELLS — continuous, so 3.5 is the
// middle of cell 3 — with a yaw `r` in DEGREES, clockwise seen from above:
// r = 0 means the model's front faces SOUTH (+y), 90 west, 180 north, 270
// east. `z` lifts it that many METRES off the floor it stands on (a bottle on
// a table, a sign on a wall). In three.js terms: position (x·CELL, floor + z,
// y·CELL) and rotation.y = -r in radians.
//
// TILT (Josh, Oct 2026: "xyz axis rotation for props"): `rx` tips a prop
// about its own left-right axis (positive = its front goes DOWN) and `rz`
// rolls it about its own front-back axis (positive = it leans to ITS left),
// both in degrees, both applied after the yaw — three.js Euler order "YXZ":
// rotation.set(rx·π/180, -r·π/180, rz·π/180, "YXZ"). Turning a room leaves a
// prop's tilt alone; MIRRORING one swaps its left for its right, so the roll
// changes sign and the pitch does not.
//
// SHAPES (the same round: "geometrical shape that I can place and texture,
// scale, resize"): cube, cylinder, pyramid, cone, sphere, pillars and a wedge,
// DRAWN by the game like the signs (client/src/backrooms/shapes.ts). A shape
// placement carries its own size in metres (`sx` wide, `sy` tall, `sz`
// deep, before its turn), a surface to wear (`tex`, any id in surfaces.ts —
// a wall, floor or ceiling texture, or one Josh uploaded), a tint (`col`)
// and whether people walk round it (`solid`, default true).

import CATALOG_JSON from "./props-catalog.json";
import { findSurface } from "./surfaces";

export type KitMount = "floor" | "wall" | "ceiling";

export interface KitVariant {
  /** File stem under /assets/propkit/ (`<file>.gltf`). */
  file: string;
  label: string;
  /** Width (x) · height · depth (z) in metres, as built — unrotated. */
  size: [number, number, number];
}

export interface KitProp {
  id: string;
  name: string;
  /** [section, shelf] — the editor's category tree. */
  cat: [string, string];
  tags: string[];
  theme: string[];
  /** Which levels the editor offers it on by default (0, 1, 2). */
  levels: number[];
  mount: KitMount;
  /** Blocks movement. Small things, rugs and things on walls don't. */
  solid: boolean;
  /** "open": the file carries an "open" clip and the game swings it open as
   *  somebody walks up (the intake's doors — scripts/props/intake.mjs). */
  anim?: string;
  /** Who made it and under what licence, for a downloaded model. */
  credit?: string;
  /** Drawn by the game rather than loaded from a file: "sign" carries the
   *  words in the placement's `text` (KIT_SIGNS below); "shape" its size,
   *  surface and tint (KIT_SHAPES). */
  builtin?: "sign" | "shape";
  variants: KitVariant[];
}

/** A prop placed in a room design (tile-local) or a map (sector cells). */
export interface KitPlace {
  /** Catalogue id. */
  p: string;
  /** Variant NUMBER, 1-based (the `--n` in its file name). Default 1. */
  v?: number;
  x: number;
  y: number;
  /** Yaw in degrees, clockwise from facing south. Default 0. */
  r?: number;
  /** Metres above the floor. Default 0. */
  z?: number;
  /** The share of the room's copies it appears in, percent (1–100). Default
   *  100. Rolled once per copy by the generator (marks.ts copyRoll). */
  c?: number;
  /** What a SIGN says (the builtin sign props only). */
  text?: string;
  /** Tilt in degrees, after the yaw (see the header): pitch about the prop's
   *  own left-right axis, roll about its front-back axis. Default 0. */
  rx?: number;
  rz?: number;
  /** A SHAPE's size in metres: width, height, depth, before its turn.
   *  Default: its variant's size. */
  sx?: number;
  sy?: number;
  sz?: number;
  /** A SHAPE's surface — any surface id (surfaces.ts). Absent = plain paint. */
  tex?: string;
  /** A SHAPE's colour, "#rrggbb" — the paint, or a tint over its surface. */
  col?: string;
  /** A SHAPE people walk through (false). Default true — a shape is solid. */
  solid?: boolean;
}

export const KIT_BASE: string = (CATALOG_JSON as { base: string }).base;
/** Every prop built from a model file (the catalogue). */
export const KIT_PROPS: readonly KitProp[] = (CATALOG_JSON as unknown as { props: KitProp[] }).props;

/** The most words a sign holds. */
export const SIGN_MAX = 60;

