/** The catalogue, the signs and the shapes — everything the editor offers. */
export const KIT_ALL: readonly KitProp[] = [...KIT_PROPS, ...KIT_SIGNS, ...KIT_SHAPES];
export const KIT: ReadonlyMap<string, KitProp> = new Map(KIT_ALL.map((p) => [p.id, p]));
/** Is this variant file a sign the game draws? */
export const isSignFile = (file: string): boolean => file.startsWith("sign-");
/** …or a shape it draws? */
export const isShapeFile = (file: string): boolean => file.startsWith("shape-");
/** The largest and smallest a shape may be, metres per side. */
export const SHAPE_MIN = 0.05;
export const SHAPE_MAX = 30;

/** Metres per cell — the map grid (worldgen's CELL; duplicated so this module
 *  stays import-free for the editor). */
export const KIT_CELL = 2;

/** Anything shorter than this is stepped over rather than walked around. */
export const KIT_STEP_OVER = 0.3;

export function kitVariant(pl: KitPlace): KitVariant | null {
  const prop = KIT.get(pl.p);
  if (!prop) return null;
  return prop.variants[(pl.v ?? 1) - 1] ?? null;
}

/** A placement's size in metres — [width, height, depth] before its turn.
 *  A shape's is its own; everything else is its model's. */
export function kitSize(pl: KitPlace): [number, number, number] | null {
  const v = kitVariant(pl);
  if (!v) return null;
  if (!isShapeFile(v.file)) return v.size;
  return [pl.sx ?? v.size[0], pl.sy ?? v.size[1], pl.sz ?? v.size[2]];
}

/** Does this placement block movement? Solid, tall enough, standing on the
 *  floor (a bottle on a table blocks nothing — the table does). */
export function kitBlocks(pl: KitPlace): boolean {
  const prop = KIT.get(pl.p);
  const size = kitSize(pl);
  if (!prop || !size || !prop.solid || prop.mount !== "floor") return false;
  if (prop.builtin === "shape" && pl.solid === false) return false;
  return (pl.z ?? 0) < KIT_STEP_OVER && size[1] >= KIT_STEP_OVER;
}

/** The axis-aligned half-extents, in CELLS, of a placement's footprint after
 *  its yaw — what the client's collision boxes are. */
export function kitExtents(pl: KitPlace): { rx: number; ry: number } {
  const size = kitSize(pl);
  if (!size) return { rx: 0, ry: 0 };
  const a = ((pl.r ?? 0) * Math.PI) / 180;
  const c = Math.abs(Math.cos(a));
  const s = Math.abs(Math.sin(a));
  const w = size[0] / KIT_CELL;
  const d = size[2] / KIT_CELL;
  return { rx: (c * w + s * d) / 2, ry: (s * w + c * d) / 2 };
}

/** Is the point (px, py) inside the placement's (rotated) footprint? */
export function kitCovers(pl: KitPlace, px: number, py: number): boolean {
  const size = kitSize(pl);
  if (!size) return false;
  const a = ((pl.r ?? 0) * Math.PI) / 180;
  // into the prop's own frame: undo the yaw (clockwise from above = +a in a
  // y-down map), so the model's x runs along its width and y along its depth
  const dx = px - pl.x;
  const dy = py - pl.y;
  const lx = dx * Math.cos(a) + dy * Math.sin(a);
  const ly = -dx * Math.sin(a) + dy * Math.cos(a);
  return Math.abs(lx) <= size[0] / KIT_CELL / 2 && Math.abs(ly) <= size[2] / KIT_CELL / 2;
}

/** Normalise a yaw to [0, 360). */
export const kitYaw = (r: number): number => ((Math.round(r * 1000) / 1000) % 360 + 360) % 360;

/** Everything wrong with one placement, as plain sentences (the editor's
 *  lint panel and the library harness both print these). */
export function kitProblems(pl: KitPlace): string[] {
  const out: string[] = [];
  const prop = KIT.get(pl.p);
  if (!prop) return [`there is no prop called "${pl.p}"`];
  const n = pl.v ?? 1;
  if (!Number.isInteger(n) || n < 1 || n > prop.variants.length) out.push(`${prop.name} has ${prop.variants.length} variant${prop.variants.length === 1 ? "" : "s"}, not ${n}`);
  for (const k of ["x", "y", "r", "z", "rx", "rz", "sx", "sy", "sz"] as const) {
    const val = pl[k];
    if (val !== undefined && (typeof val !== "number" || !Number.isFinite(val))) out.push(`${prop.name}: ${k} is not a number`);
  }
  for (const k of ["rx", "rz"] as const) {
    const val = pl[k];
    if (typeof val === "number" && (val < -180 || val > 180)) out.push(`${prop.name}: its tilt must be -180–180°`);
  }
  if (prop.builtin === "shape") {
    for (const k of ["sx", "sy", "sz"] as const) {
      const val = pl[k];
      if (typeof val === "number" && (val < SHAPE_MIN || val > SHAPE_MAX)) out.push(`${prop.name}: each side must be ${SHAPE_MIN}–${SHAPE_MAX} metres`);
    }
    if (pl.tex !== undefined && (typeof pl.tex !== "string" || !surfaceKindOf(pl.tex))) out.push(`${prop.name}: there is no surface called "${String(pl.tex)}"`);
    if (pl.solid !== undefined && typeof pl.solid !== "boolean") out.push(`${prop.name}: solid must be true or false`);
  } else if (pl.sx !== undefined || pl.sy !== undefined || pl.sz !== undefined || pl.tex !== undefined || pl.solid !== undefined || pl.col !== undefined) {
    out.push(`${prop.name}: only a shape takes a size, a surface, a colour or a solid setting`);
  }
  if (pl.col !== undefined && (typeof pl.col !== "string" || !/^#[0-9a-f]{6}$/i.test(pl.col))) out.push(`${prop.name}: its colour must be "#rrggbb"`);
  if ((pl.z ?? 0) < 0 || (pl.z ?? 0) > 12) out.push(`${prop.name}: z must be 0–12 metres`);
  if (pl.c !== undefined && (!Number.isFinite(pl.c) || pl.c < 1 || pl.c > 100)) out.push(`${prop.name}: its chance must be 1–100%`);
  if (pl.text !== undefined && (typeof pl.text !== "string" || pl.text.length > SIGN_MAX)) out.push(`${prop.name}: its words must be at most ${SIGN_MAX} characters`);
  return out;
}

/** Which kind of surface an id is (a shape may wear any of them), or null. */
export function surfaceKindOf(id: string): "wall" | "floor" | "ceil" | null {
  for (const k of ["wall", "floor", "ceil"] as const) if (findSurface(k, id)) return k;
  return null;
}
